import type { ProgramVideoItem } from "../types";

interface ProgramVideoSectionProps {
  videos: ProgramVideoItem[];
  onDonateClick: () => void;
}

const buttonBase: React.CSSProperties = {
  display: "inline-block",
  padding: "13px 26px",
  borderRadius: 999,
  fontWeight: 700,
  fontSize: 14,
  textDecoration: "none",
};

// The thumbnail shown before a video is played lives alongside it as the
// same filename with a .jpg extension (e.g. program-video.mp4 ->
// program-video.jpg), generated by extracting a frame from the video.
function posterFor(videoFilename: string): string {
  return `/videos/${videoFilename.replace(/\.[^./]+$/, ".jpg")}`;
}

export default function ProgramVideoSection({ videos, onDonateClick }: ProgramVideoSectionProps) {
  if (videos.length === 0) return null;

  // Button visibility is a single shared row below all videos, so it's read
  // from the first row only — later rows don't need those columns filled in.
  const { showDonateButton, showShopButton, showNewsletterButton } = videos[0];

  return (
    <div style={{ padding: "clamp(48px,7vw,72px) clamp(16px,6vw,40px)", textAlign: "center" }}>
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: 48,
          maxWidth: 720,
          margin: "0 auto",
        }}
      >
        {videos.map((video, i) => (
          <div key={i}>
            <h2
              style={{
                fontFamily: "'Baloo 2',sans-serif",
                fontWeight: 700,
                textTransform: "uppercase",
                color: "#282882",
                fontSize: 22,
                margin: "0 0 16px",
              }}
            >
              {video.heading}
            </h2>
            {video.description && (
              <p
                style={{
                  fontSize: 14,
                  lineHeight: 1.6,
                  color: "#5a5850",
                  maxWidth: 560,
                  margin: "0 auto 28px",
                }}
              >
                {video.description}
              </p>
            )}
            <video
              controls
              playsInline
              preload="metadata"
              poster={posterFor(video.videoFilename)}
              style={{
                width: "100%",
                borderRadius: 16,
                display: "block",
                margin: "0 auto",
                background: "#000",
              }}
            >
              <source src={`/videos/${video.videoFilename}`} type="video/mp4" />
            </video>
          </div>
        ))}
      </div>
      <div
        style={{
          display: "flex",
          flexWrap: "wrap",
          gap: 12,
          justifyContent: "center",
          marginTop: 40,
        }}
      >
        {showDonateButton && (
          <a
            href="https://square.link/u/wzRTsGub"
            target="_blank"
            rel="noreferrer"
            onClick={onDonateClick}
            style={{ ...buttonBase, background: "#FFDD00", color: "#1c1b18" }}
          >
            Donate Now
          </a>
        )}
        {showShopButton && (
          <a
            href="#square-shop"
            style={{ ...buttonBase, border: "2px solid #282882", color: "#282882" }}
          >
            Shop the Books
          </a>
        )}
        {showNewsletterButton && (
          <a
            href="#newsletter-section"
            style={{ ...buttonBase, border: "2px solid #282882", color: "#282882" }}
          >
            Join the Newsletter
          </a>
        )}
      </div>
    </div>
  );
}
